<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;
use App\Modules\CommercialRental\Services\CommercialRentalVehicleService;use App\Modules\CommercialRental\Services\CommercialRentalProviderService;use App\Modules\CommercialRental\Services\CommercialRentalCategoryService;
use App\Modules\CommercialRental\Services\CommercialRentalImageUploadService;
final class CommercialRentalVehicleController extends Controller{private CommercialRentalVehicleService$s;private CommercialRentalProviderService$p;private CommercialRentalCategoryService$c;private Authorization$a;private CommercialRentalImageUploadService$i;public function __construct(){$this->s=new CommercialRentalVehicleService();$this->p=new CommercialRentalProviderService();$this->c=new CommercialRentalCategoryService();$this->a=new Authorization();$this->i=new CommercialRentalImageUploadService();}private function ok(string$p,string$r='/commercial-rentals/vehicles'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException$e){flash('error',$e->getMessage());redirect($r);return false;}}private function data(int$t,array$x=[]):array{return['providers'=>$this->p->all($t),'categories'=>$this->c->all($t)]+$x;}public function index():void{if(!$this->ok('commercial_rental.vehicles.view'))return;$this->view('CommercialRental::Vehicles.index',['title'=>'Vehicles & Equipment','vehicles'=>$this->s->all((int)Auth::tenantId())]);}public function create():void{if(!$this->ok('commercial_rental.vehicles.create'))return;$this->view('CommercialRental::Vehicles.create',$this->data((int)Auth::tenantId(),['title'=>'Add Vehicle / Equipment']));}public function store():void{if(!$this->ok('commercial_rental.vehicles.create'))return;try{$_POST['photo_path']=$_POST['existing_photo_path']??''; if(!empty($_FILES['photo']['name'])) $_POST['photo_path']=$this->i->store($_FILES['photo']); $this->s->create((int)Auth::tenantId(),$_POST,(int)Auth::id());flash('success','Vehicle/equipment created.');redirect('/commercial-rentals/vehicles');}catch(Throwable$e){$this->view('CommercialRental::Vehicles.create',$this->data((int)Auth::tenantId(),['title'=>'Add Vehicle / Equipment','error'=>$e->getMessage(),'old'=>$_POST]));}}public function show(int$id):void{if(!$this->ok('commercial_rental.vehicles.view'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Vehicles.show',['title'=>$r['name'],'record'=>$r]);}public function edit(int$id):void{if(!$this->ok('commercial_rental.vehicles.edit'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Vehicles.edit',$this->data((int)Auth::tenantId(),['title'=>'Edit Vehicle / Equipment','record'=>$r]));}public function update(int$id):void{if(!$this->ok('commercial_rental.vehicles.edit'))return;try{$_POST['photo_path']=$_POST['existing_photo_path']??(($this->s->find((int)Auth::tenantId(),$id)['photo_path']??'')); if(!empty($_FILES['photo']['name'])) $_POST['photo_path']=$this->i->store($_FILES['photo']); $this->s->update((int)Auth::tenantId(),$id,$_POST,(int)Auth::id());flash('success','Vehicle/equipment updated.');redirect('/commercial-rentals/vehicles/'.$id);}catch(Throwable$e){$this->view('CommercialRental::Vehicles.edit',$this->data((int)Auth::tenantId(),['title'=>'Edit Vehicle / Equipment','record'=>$_POST,'error'=>$e->getMessage()]));}}public function destroy(int$id):void{if(!$this->ok('commercial_rental.vehicles.delete'))return;$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Vehicle/equipment deleted.');redirect('/commercial-rentals/vehicles');}}
